const config = {
  empresa: {
    nome: "NOME_DO_CLIENTE",
    telefone_responsavel: "55DDDNUMERO",
    waha_base_url: "http://IP_DA_VPS:3000",
    waha_api_key: "SUA_WAHA_API_KEY",
    session: "default"
  },
  supabase: {
    url: "https://SEU_PROJECT_REF.supabase.co",
    service_role_key: "SUA_SUPABASE_SERVICE_ROLE_KEY"
  }
};

const now = new Date();
const firstDay = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const lastDay = new Date(now.getFullYear(), now.getMonth(), 0);

return [{ json: { config, firstDay, lastDay } }];

const ags = $json;

let total = ags.length;
let chegou = ags.filter(a => a.status === 'CLIENTE_CHEGOU').length;
let faltou = ags.filter(a => a.status === 'CLIENTE_FALTOU').length;

let simples = ags.filter(a => a.servico === 'simples');
let detalhada = ags.filter(a => a.servico === 'detalhada');

let receitaSimples = simples.reduce((acc, a) => acc + (a.preco || 0), 0);
let receitaDetalhada = detalhada.reduce((acc, a) => acc + (a.preco || 0), 0);

let receitaTotal = receitaSimples + receitaDetalhada;
let ticket = total > 0 ? receitaTotal / total : 0;

let taxaPresenca = total > 0 ? (chegou / total) * 100 : 0;
let taxaFalta = total > 0 ? (faltou / total) * 100 : 0;

return [{
  json: {
    total,
    chegou,
    faltou,
    receitaTotal,
    receitaSimples,
    receitaDetalhada,
    simples: simples.length,
    detalhada: detalhada.length,
    ticket,
    taxaPresenca,
    taxaFalta,
    config: $item(0).$node["Config + Datas"].json.config
  }
}];

const d = $json;

const text = `📊 Relatório mensal - ${d.config.empresa.nome}

Agendamentos: ${d.total}
Compareceram: ${d.chegou}
Faltaram: ${d.faltou}

📈 Taxa de presença: ${d.taxaPresenca.toFixed(1)}%
📉 Taxa de falta: ${d.taxaFalta.toFixed(1)}%

🧼 Simples: ${d.simples} (R$ ${d.receitaSimples})
✨ Detalhada: ${d.detalhada} (R$ ${d.receitaDetalhada})

💰 Receita total: R$ ${d.receitaTotal}
💳 Ticket médio: R$ ${d.ticket.toFixed(2)}`;

return [{ json: { ...d, text } }];
